export const CONCEPTS = "@prefix m5:      <https://maker-5.cloud/ontology#> .\n@prefix skos:    <http://www.w3.org/2004/02/skos/core#> .\n\n# ============================================================\n# Concept schemes (SKOS), v0.1.\n#\n# New kinds are added HERE, as data: no code or schema change. Each concept\n# needs an English prefLabel (the master); German and French are expected.\n# ============================================================\n\nm5:BlockTypes a skos:ConceptScheme ;\n    skos:prefLabel \"Kinds of blocks\"@en , \"Arten von Blöcken\"@de , \"Types de blocs\"@fr ;\n    skos:hasTopConcept m5:Electronic , m5:Mechanical .\n\nm5:Electronic a skos:Concept ; skos:inScheme m5:BlockTypes ; skos:topConceptOf m5:BlockTypes ;\n    skos:prefLabel \"Electronic\"@en , \"Elektronik\"@de , \"Électronique\"@fr .\n\nm5:Mechanical a skos:Concept ; skos:inScheme m5:BlockTypes ; skos:topConceptOf m5:BlockTypes ;\n    skos:prefLabel \"Mechanical\"@en , \"Mechanik\"@de , \"Mécanique\"@fr .\n\nm5:ProposalStates a skos:ConceptScheme ;\n    skos:prefLabel \"States of a proposal\"@en , \"Status eines Vorschlags\"@de , \"États d'une proposition\"@fr ;\n    skos:hasTopConcept m5:Proposed , m5:Approved , m5:Rejected .\n\nm5:Proposed a skos:Concept ; skos:inScheme m5:ProposalStates ; skos:topConceptOf m5:ProposalStates ;\n    skos:prefLabel \"Proposed\"@en , \"Vorgeschlagen\"@de , \"Proposée\"@fr .\n\nm5:Approved a skos:Concept ; skos:inScheme m5:ProposalStates ; skos:topConceptOf m5:ProposalStates ;\n    skos:prefLabel \"Approved\"@en , \"Genehmigt\"@de , \"Approuvée\"@fr .\n\nm5:Rejected a skos:Concept ; skos:inScheme m5:ProposalStates ; skos:topConceptOf m5:ProposalStates ;\n    skos:prefLabel \"Rejected\"@en , \"Abgelehnt\"@de , \"Rejetée\"@fr .\n\nm5:TrackingModes a skos:ConceptScheme ;\n    skos:prefLabel \"How an article is tracked\"@en , \"Wie ein Artikel erfasst wird\"@de , \"Comment un article est suivi\"@fr ;\n    skos:hasTopConcept m5:Bulk , m5:Serialised .\n\nm5:Bulk a skos:Concept ; skos:inScheme m5:TrackingModes ; skos:topConceptOf m5:TrackingModes ;\n    skos:prefLabel \"In bulk\"@en , \"Als Menge\"@de , \"En vrac\"@fr .\n\nm5:Serialised a skos:Concept ; skos:inScheme m5:TrackingModes ; skos:topConceptOf m5:TrackingModes ;\n    skos:prefLabel \"Unit by unit\"@en , \"Einzeln\"@de , \"À l'unité\"@fr .\n\nm5:ArticleCategories a skos:ConceptScheme ;\n    skos:prefLabel \"Categories of articles\"@en , \"Artikelkategorien\"@de , \"Catégories d'articles\"@fr ;\n    skos:hasTopConcept m5:CategoryCompute , m5:CategoryStorage , m5:CategoryElectronicComponent , m5:CategoryMechanicalPart , m5:CategoryCable , m5:CategoryConsumable , m5:CategoryTool .\n\nm5:CategoryCompute a skos:Concept ; skos:inScheme m5:ArticleCategories ; skos:topConceptOf m5:ArticleCategories ;\n    skos:prefLabel \"Compute\"@en , \"Rechner\"@de , \"Calcul\"@fr .\n\nm5:CategoryStorage a skos:Concept ; skos:inScheme m5:ArticleCategories ; skos:topConceptOf m5:ArticleCategories ;\n    skos:prefLabel \"Storage\"@en , \"Speicher\"@de , \"Stockage\"@fr .\n\nm5:CategoryElectronicComponent a skos:Concept ; skos:inScheme m5:ArticleCategories ; skos:topConceptOf m5:ArticleCategories ;\n    skos:prefLabel \"Electronic component\"@en , \"Elektronisches Bauteil\"@de , \"Composant électronique\"@fr .\n\nm5:CategoryMechanicalPart a skos:Concept ; skos:inScheme m5:ArticleCategories ; skos:topConceptOf m5:ArticleCategories ;\n    skos:prefLabel \"Mechanical part\"@en , \"Mechanisches Teil\"@de , \"Pièce mécanique\"@fr .\n\nm5:CategoryCable a skos:Concept ; skos:inScheme m5:ArticleCategories ; skos:topConceptOf m5:ArticleCategories ;\n    skos:prefLabel \"Cable\"@en , \"Kabel\"@de , \"Câble\"@fr .\n\nm5:CategoryConsumable a skos:Concept ; skos:inScheme m5:ArticleCategories ; skos:topConceptOf m5:ArticleCategories ;\n    skos:prefLabel \"Consumable\"@en , \"Verbrauchsmaterial\"@de , \"Consommable\"@fr .\n\nm5:CategoryTool a skos:Concept ; skos:inScheme m5:ArticleCategories ; skos:topConceptOf m5:ArticleCategories ;\n    skos:prefLabel \"Tool\"@en , \"Werkzeug\"@de , \"Outil\"@fr .\n\nm5:PinRoles a skos:ConceptScheme ;\n    skos:prefLabel \"Roles of pins\"@en , \"Rollen von Pins\"@de , \"Rôles des broches\"@fr ;\n    skos:hasTopConcept m5:PinPower , m5:PinGround , m5:PinSignal , m5:PinAudio , m5:PinVideo , m5:PinData .\n\nm5:PinPower a skos:Concept ; skos:inScheme m5:PinRoles ; skos:topConceptOf m5:PinRoles ;\n    skos:prefLabel \"Power\"@en , \"Versorgung\"@de , \"Alimentation\"@fr .\n\nm5:PinGround a skos:Concept ; skos:inScheme m5:PinRoles ; skos:topConceptOf m5:PinRoles ;\n    skos:prefLabel \"Ground\"@en , \"Masse\"@de , \"Masse\"@fr .\n\nm5:PinSignal a skos:Concept ; skos:inScheme m5:PinRoles ; skos:topConceptOf m5:PinRoles ;\n    skos:prefLabel \"Signal\"@en , \"Signal\"@de , \"Signal\"@fr .\n\nm5:PinAudio a skos:Concept ; skos:inScheme m5:PinRoles ; skos:topConceptOf m5:PinRoles ;\n    skos:prefLabel \"Audio\"@en , \"Audio\"@de , \"Audio\"@fr .\n\nm5:PinVideo a skos:Concept ; skos:inScheme m5:PinRoles ; skos:topConceptOf m5:PinRoles ;\n    skos:prefLabel \"Video\"@en , \"Video\"@de , \"Vidéo\"@fr .\n\nm5:PinData a skos:Concept ; skos:inScheme m5:PinRoles ; skos:topConceptOf m5:PinRoles ;\n    skos:prefLabel \"Data\"@en , \"Daten\"@de , \"Données\"@fr .\n\nm5:SupplyStates a skos:ConceptScheme ;\n    skos:prefLabel \"Supply\"@en , \"Beschaffung\"@de , \"Approvisionnement\"@fr ;\n    skos:hasTopConcept m5:SupplyThere , m5:SupplyInHand , m5:SupplyToBuy .\n\nm5:SupplyThere a skos:Concept ; skos:inScheme m5:SupplyStates ; skos:topConceptOf m5:SupplyStates ;\n    skos:prefLabel \"Already there\"@en , \"Schon vorhanden\"@de , \"Déjà là\"@fr .\n\nm5:SupplyInHand a skos:Concept ; skos:inScheme m5:SupplyStates ; skos:topConceptOf m5:SupplyStates ;\n    skos:prefLabel \"In hand\"@en , \"Zur Hand\"@de , \"Sous la main\"@fr .\n\nm5:SupplyToBuy a skos:Concept ; skos:inScheme m5:SupplyStates ; skos:topConceptOf m5:SupplyStates ;\n    skos:prefLabel \"To buy or build\"@en , \"Zu kaufen oder bauen\"@de , \"À acheter ou construire\"@fr .\n";
export const SHAPES = "@prefix m5:     <https://maker-5.cloud/ontology#> .\n@prefix m5sh:   <https://maker-5.cloud/shapes#> .\n@prefix sh:     <http://www.w3.org/ns/shacl#> .\n@prefix skos:   <http://www.w3.org/2004/02/skos/core#> .\n@prefix schema: <https://schema.org/> .\n@prefix prov:   <http://www.w3.org/ns/prov#> .\n@prefix xsd:    <http://www.w3.org/2001/XMLSchema#> .\n\n# ============================================================\n# SHACL shapes, v0.1: the validation gates an A-Box must pass. Validate an\n# A-Box TOGETHER with tbox/maker-5-concepts.ttl, so a kind can be checked\n# against its scheme. The cloud refuses an A-Box that does not conform\n# (ADR-0007), and that includes an agent's proposal.\n# ============================================================\n\nm5sh:InBlockTypes a sh:NodeShape ;\n    sh:property [ sh:path skos:inScheme ; sh:hasValue m5:BlockTypes ] .\n\nm5sh:InProposalStates a sh:NodeShape ;\n    sh:property [ sh:path skos:inScheme ; sh:hasValue m5:ProposalStates ] .\n\nm5sh:ProductShape a sh:NodeShape ;\n    sh:targetClass m5:Product ;\n    sh:property [ sh:path schema:name ; sh:minCount 1 ; sh:message \"A product needs a name.\"@en ] .\n\nm5sh:BlockShape a sh:NodeShape ;\n    sh:targetClass m5:Block ;\n    sh:property [\n        sh:path m5:usesArticle ;\n        sh:maxCount 1 ;\n        sh:nodeKind sh:IRI ;\n        sh:pattern \"^https://maker-5\\\\.cloud/id/article/a-[23456789abcdefghjkmnpqrstuvwxyz]{10}$\" ;\n        sh:message \"A block or module is built from one article of the workspace's stock.\"@en ;\n    ] ;\n    sh:property [\n        sh:path m5:quantity ;\n        sh:maxCount 1 ;\n        sh:datatype xsd:integer ;\n        sh:minInclusive 1 ;\n        sh:message \"A quantity is a whole number, at least 1.\"@en ;\n    ] ;\n    sh:property [ sh:path schema:name ; sh:minCount 1 ; sh:message \"A block needs a name.\"@en ] ;\n    sh:property [\n        sh:path m5:blockType ;\n        sh:maxCount 1 ;\n        sh:node m5sh:InBlockTypes ;\n        sh:message \"A block's kind is one concept from m5:BlockTypes.\"@en ;\n    ] ;\n    sh:property [\n        sh:path m5:partOf ;\n        sh:class m5:Product ;\n        sh:message \"A block is part of a product.\"@en ;\n    ] .\n\nm5sh:SoftwareModuleShape a sh:NodeShape ;\n    sh:targetClass m5:SoftwareModule ;\n    sh:property [\n        sh:path m5:usesArticle ;\n        sh:maxCount 1 ;\n        sh:nodeKind sh:IRI ;\n        sh:pattern \"^https://maker-5\\\\.cloud/id/article/a-[23456789abcdefghjkmnpqrstuvwxyz]{10}$\" ;\n        sh:message \"A block or module is built from one article of the workspace's stock.\"@en ;\n    ] ;\n    sh:property [\n        sh:path m5:quantity ;\n        sh:maxCount 1 ;\n        sh:datatype xsd:integer ;\n        sh:minInclusive 1 ;\n        sh:message \"A quantity is a whole number, at least 1.\"@en ;\n    ] ;\n    sh:property [ sh:path schema:name ; sh:minCount 1 ; sh:message \"A software module needs a name.\"@en ] ;\n    sh:property [\n        sh:path m5:partOf ;\n        sh:class m5:Product ;\n        sh:message \"A software module is part of a product.\"@en ;\n    ] .\n\nm5sh:InterfaceShape a sh:NodeShape ;\n    sh:targetClass m5:Interface ;\n    sh:property [ sh:path schema:name ; sh:minCount 1 ; sh:message \"An interface needs a name.\"@en ] ;\n    sh:property [\n        sh:path m5:connects ;\n        sh:minCount 2 ;\n        sh:message \"An interface connects at least two blocks or software modules.\"@en ;\n    ] .\n\nm5sh:ProposalShape a sh:NodeShape ;\n    sh:targetClass m5:Proposal ;\n    sh:property [ sh:path schema:name ; sh:minCount 1 ; sh:message \"A proposal needs a title.\"@en ] ;\n    sh:property [\n        sh:path m5:proposalState ;\n        sh:minCount 1 ; sh:maxCount 1 ;\n        sh:node m5sh:InProposalStates ;\n        sh:message \"A proposal has exactly one state from m5:ProposalStates.\"@en ;\n    ] ;\n    sh:property [\n        sh:path prov:wasAttributedTo ;\n        sh:minCount 1 ;\n        sh:message \"A proposal says which agent made it (prov:wasAttributedTo).\"@en ;\n    ] .\n\n# --- Hardware and supply (ADR-0014) -----------------------------------\n\nm5sh:InPinRoles a sh:NodeShape ;\n    sh:property [ sh:path skos:inScheme ; sh:hasValue m5:PinRoles ] .\n\nm5sh:InSupplyStates a sh:NodeShape ;\n    sh:property [ sh:path skos:inScheme ; sh:hasValue m5:SupplyStates ] .\n\nm5sh:PinShape a sh:NodeShape ;\n    sh:targetClass m5:Pin ;\n    sh:property [ sh:path schema:name ; sh:minCount 1 ; sh:message \"A pin needs a name.\"@en ] ;\n    sh:property [ sh:path m5:pinOf ; sh:minCount 1 ; sh:maxCount 1 ; sh:class m5:Block ;\n                  sh:message \"A pin belongs to exactly one block.\"@en ] ;\n    sh:property [ sh:path m5:pinNumber ; sh:maxCount 1 ; sh:datatype xsd:integer ] ;\n    sh:property [ sh:path m5:pinRole ; sh:maxCount 1 ; sh:node m5sh:InPinRoles ;\n                  sh:message \"A pin's role is a concept from m5:PinRoles.\"@en ] .\n\nm5sh:WireShape a sh:NodeShape ;\n    sh:targetClass m5:Wire ;\n    sh:property [ sh:path m5:wireEnd ; sh:minCount 2 ; sh:maxCount 2 ; sh:class m5:Pin ;\n                  sh:message \"A wire joins exactly two pins.\"@en ] ;\n    sh:property [ sh:path m5:wireColor ; sh:maxCount 1 ; sh:datatype xsd:string ] ;\n    sh:property [ sh:path m5:alongInterface ; sh:maxCount 1 ; sh:class m5:Interface ] .\n\nm5sh:BlockSupplyShape a sh:NodeShape ;\n    sh:targetClass m5:Block ;\n    sh:property [ sh:path m5:supplyState ; sh:maxCount 1 ; sh:node m5sh:InSupplyStates ;\n                  sh:message \"A block's supply is a concept from m5:SupplyStates.\"@en ] ;\n    sh:property [ sh:path m5:canvasX ; sh:maxCount 1 ; sh:datatype xsd:integer ] ;\n    sh:property [ sh:path m5:canvasY ; sh:maxCount 1 ; sh:datatype xsd:integer ] ;\n    sh:property [ sh:path m5:fritzingPart ; sh:maxCount 1 ; sh:datatype xsd:string ;\n                  sh:pattern \"^(core|contrib)/[^/]{1,200}\\\\.fzp$\" ;\n                  sh:message \"A block's Fritzing part is one file of the library's core or contrib folder.\"@en ] .\n\nm5sh:ModuleHostShape a sh:NodeShape ;\n    sh:targetClass m5:SoftwareModule ;\n    sh:property [ sh:path m5:runsOn ; sh:maxCount 1 ; sh:class m5:Block ;\n                  sh:message \"A software module runs on at most one block.\"@en ] .\n";
